                int tz, tz_hour, tz_min;

                p = tail + 1;
                s_tm.tm_year = tmp - 1900; /* 'struct tm' starts years in 1900 */

                if (get_part(&p, &s_tm.tm_mon, 1, 13, '-', "month") < 0) return -1;
