                if (get_part(&p, &s_tm.tm_hour, 0, 23, ':', "hour") < 0) return -1;
                if (get_part(&p, &s_tm.tm_min, 0, 59, ':', "minute") < 0) return -1;
                if (get_part(&p, &s_tm.tm_sec, 0, 60, '\0', "seconds") < 0) return -1;

